     assert page.locator('.welcome-recent-mark').evaluate_all('(nodes)=>nodes.every(n=>{const b=n.getBoundingClientRect();return b.width<=38.1&&b.height<=38.1&&[...n.querySelectorAll("img,svg")].every(x=>{const r=x.getBoundingClientRect();return r.width<=23.1&&r.height<=23.1&&r.left>=b.left&&r.right<=b.right+.1;});})')
