    page.set_viewport_size({'width':2048,'height':1222});page.wait_for_timeout(350);page.screenshot(path=str(out/'home-three-icons.png'));page.evaluate('recent=>{__qa.studio.profile.recent=recent;__qa.studio.renderHome();}',original_recent)
    checks.append('ASM, C and nC icons from the reported screenshot fit their complete glyphs and leave readable labels across four viewport sizes')
