    page.locator('.melody-utilities-toggle').click();page.locator('[data-melody-task=dossier]').click();expect(page.locator('.r2-dossier')).to_be_visible();expect(page.locator('.r2-evidence-summary')).to_contain_text('Sin evidencia');page.wait_for_timeout(450);page.screenshot(path=str(out/'dossier.png'));page.locator('[data-dossier-ask]').click();expect(page.locator('#ai-input')).to_have_value(re.compile('dossier'));assert page.evaluate('!__qa.platform.aiJob');checks.append('Dossier de fallo reviews source and diagnostic evidence without inventing an execution or sending AI')
    page.evaluate('__qa.dock.show("assistant");__qa.editor.insertText("value=int(input())\\nprint(value+2)\\n",true)')
