    page.locator('[data-lantern=rules]').first.click();page.locator('[data-lantern-compare]').click();expect(page.locator('.r2-compare')).to_be_visible();expect(page.locator('.r2-compare>header')).to_contain_text('difieren');page.screenshot(path=str(out/'revision-comparison.png'));page.keyboard.press('Escape');checks.append('The revision comparison opens two completed real Lantern records and starts no new execution')
    page.locator('[data-lantern=rules]').first.click();page.locator('[data-lantern-matrix]').click();page.wait_for_timeout(350);page.screenshot(path=str(out/'matrix-form.png'));page.locator('[name=stdin-0]').fill('4\n');page.locator('[name=output-0]').fill('7\n');page.locator('[name=stdin-1]').fill('5\n');page.locator('[name=output-1]').fill('8\n');page.locator('[data-cases-save]').click();expect(page.locator('[data-cases-saved]')).to_contain_text('guardados');page.keyboard.press('Escape');page.locator('[data-lantern=rules]').first.click();page.locator('[data-lantern-matrix]').click();expect(page.locator('[name=stdin-0]')).to_have_value('4\n');expect(page.locator('[name=output-1]')).to_have_value('8\n');checks.append('Saved matrix cases reopen with their original inputs and expected outputs');page.locator('.r2-matrix-form .primary-button').click();page.locator('[data-matrix-run]').click();expect(page.locator('.r2-matrix-result')).to_be_visible(timeout=30000);expect(page.locator('.r2-matrix-result>header')).to_contain_text('2 de 2');page.screenshot(path=str(out/'matrix.png'));page.keyboard.press('Escape');checks.append('The reviewed matrix executes both real input cases sequentially, shows their results and preserves the source')
    page.evaluate('document.querySelector("#lantern-inline")?.remove(); __qa.studio.debug()');expect(page.locator('.debug-page')).to_be_visible();page.locator('#debug-file').select_option('debug.py');page.locator('.debug-intro').click();page.keyboard.press('F5');page.wait_for_function('__qa.studio.debugWorkspace.state?.status==="paused"');page.keyboard.press('F10');page.wait_for_function('__qa.studio.debugWorkspace.state?.line===2');page.locator('[data-debug-reference]').click();expect(page.locator('[data-debug-reference]')).to_have_attribute('aria-pressed','true');page.locator('.debug-intro').click();page.keyboard.press('F10');page.wait_for_function('__qa.studio.debugWorkspace.state?.line===3');expect(page.locator('.variable-row.variable-changed')).to_contain_text('value');page.locator('[aria-label="Filtrar variables"]').fill('missing');expect(page.locator('.variable-row')).to_have_count(0);page.locator('[aria-label="Filtrar variables"]').fill('value');expect(page.locator('.variable-row')).to_have_count(1);page.screenshot(path=str(out/'debug.png'));page.context.grant_permissions(['clipboard-read','clipboard-write']);page.locator('[data-debug-copy-pause]').click();page.wait_for_function('navigator.clipboard.readText().then(t=>t.includes("variables"))');pause=page.evaluate('navigator.clipboard.readText().then(JSON.parse)');assert pause['line']==3 and any(v['name']=='value' for v in pause['variables']);checks.append('Copy pause exports the actual paused line, variables and stack to the clipboard');page.evaluate('__qa.studio.debugWorkspace.command("stop")');checks.append('Real Python debugging uses F5/F10 and filters variables while highlighting values changed between pauses')
    (ws/'console.py').write_text('import sys\nprint("CONSOLE_READY",flush=True)\nprint("INPUT_BYTES="+str(len(sys.stdin.read())))\n')
    page.evaluate('__qa.platform.closePage()');console=page.locator('#terminal-input');console.fill('run console.py');console.press('Enter');expect(page.locator('#terminal-log')).to_contain_text('CONSOLE_READY',timeout=15000);console.fill('abc');console.press('Enter');console.fill(':eof');console.press('Enter');expect(page.locator('#terminal-log')).to_contain_text('INPUT_BYTES=4',timeout=10000);page.screenshot(path=str(out/'console.png'));checks.append('The actual console starts a runtime, forwards interactive input and closes stdin with :eof')
    page.evaluate('(async()=>{__qa.platform.closePage();await __qa.openFile("example.s");__qa.profiles.apply("assembly");})()');expect(page.locator('[data-asm=run]')).to_be_visible();page.wait_for_function('__qa.profiles.assembly.catalog!==undefined');page.locator('[data-asm=step]').click();expect(page.locator('.asm-registers')).to_be_visible(timeout=20000);page.locator('[data-asm=pin]').click();page.locator('[data-asm=step]').click();expect(page.locator('.asm-registers>div.changed')).not_to_have_count(0);page.locator('[aria-label="Filtrar registros"]').fill('rax');expect(page.locator('[data-register-name=rax]')).to_be_visible();page.screenshot(path=str(out/'laboratory.png'));checks.append('Real ASM stepping pins a reference and filters changed registers without writing the source')
    tabs=page.locator('.asm-result-tabs');tabs.locator('[data-asm-result=registers]').focus();page.keyboard.press('ArrowRight');page.locator('[data-asm=follow]').click();expect(page.locator('[data-asm=follow]')).to_have_attribute('aria-pressed','false');page.locator('[data-asm=follow]').click();tabs.locator('[data-asm-result=instructions]').focus();expect(tabs.locator('[aria-selected=true]')).to_have_attribute('data-asm-result','instructions');page.keyboard.press('ArrowLeft');expect(tabs.locator('[aria-selected=true]')).to_have_attribute('data-asm-result','registers');checks.append('Laboratory tabs support keyboard navigation and preserve their real register result')
